import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Applicazioni o funzioni","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/j_teoria-degli-insiemi/jd/jd.md","filePath":"lezioni/j_teoria-degli-insiemi/jd/jd.md"}`),a={name:`lezioni/j_teoria-degli-insiemi/jd/jd.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="applicazioni-o-funzioni" tabindex="-1">Applicazioni o funzioni <a class="header-anchor" href="#applicazioni-o-funzioni" aria-label="Permalink to “Applicazioni o funzioni”">​</a></h1><p>Veniamo ora a definire mediante gli insiemi uno dei concetti più importanti della matematica: il concetto di applicazione o funzione:</p><p>Per indicarti l&#39;importanza del concetto ti elenco i sinonimi che vengono usati in matematica per indicarlo:</p><ul><li>Applicazione</li><li>Funzione</li><li>Corrispondenza univoca</li><li>Operatore</li><li>Mappa</li></ul><blockquote><p>Veramente qualche piccola differenza di significato c&#39;è; ad esempio se dici applicazione pensi al passaggio da <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> a <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> termine a termine, mentre se dici funzione poni l&#39;accento sul legame totale che c&#39;è fra <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span>; e così anche per le altre denominazioni, però queste sono sottigliezze che puoi tranquillamente trascurare.</p><p>Userò indifferentemente i termini &quot;applicazione&quot; e &quot;funzione&quot;.</p></blockquote><ul><li><a href="./jda.html">Definizione di applicazione (o funzione) fra insiemi</a></li><li><a href="./jdb.html">Codominio</a></li><li><a href="./jdc.html">Dominio</a></li><li><a href="./jdd.html">Applicazione iniettiva</a></li><li><a href="./jde.html">Applicazione suriettiva</a></li><li><a href="./jdf.html">Corrispondenza biunivoca</a></li><li><a href="./jdg.html">Insieme infinito</a></li><li><a href="./jdh.html">Applicazione composta</a></li><li><a href="./jdi.html">Applicazione inversa</a></li></ul>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};